// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Two users: A and B
        address A = address(0x1234);
        address B = address(0x5678);

        // A deposits 2 ether
        vm.deal(A, 2 ether);
        vm.prank(A);
        c.Put{value: 2 ether}(block.timestamp + 1000);

        // B deposits 1 ether
        vm.deal(B, 1 ether);
        vm.prank(B);
        c.Put{value: 1 ether}(block.timestamp + 1000);

        // Warp past unlock time
        vm.warp(block.timestamp + 2000);

        // B tries to collect 2 ether (more than his balance of 1)
        bool success;
        try c.Collect(2 ether) { success = true; } catch { success = false; }

        // In the reference, the require check prevents overflow and the collect reverts -> success == false
        // In the buggy version, require(false) always passes, balance overflows, collect succeeds -> success == true
        // The correct contract: success == false
        assertTrue(!success);
    }
}

