pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Setup: user deposits 1 ether with unlock time = block.timestamp
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.warp(1000);
        vm.prank(user);
        c.Put{value: 1 ether}(0); // unlockTime becomes block.timestamp = 1000

        // First collect: take 0.5 ether (balance=1e18, MinSum=1e18, balance>=MinSum and >=_am, timestamp>unlockTime=1000? 1000>1000 false)
        // Actually block.timestamp==unlockTime, so condition fails -> collect does nothing
        vm.warp(1001); // now timestamp > unlockTime
        vm.prank(user);
        c.Collect(0.5 ether);

        // Second collect: now balance=0.5 ether, but MinSum=1 ether
        // Reference: acc.balance >= MinSum? 0.5e18 < 1e18 => no collect (reverts or stays)
        // Buggy: no MinSum check, only balance>=_am (0.5e18>=0.5e18 true) and timestamp>unlockTime => collect succeeds
        // Use try/catch to catch revert vs success
        bool secondCollectResult;
        try c.Collect(0.5 ether) { secondCollectResult = true; } catch { secondCollectResult = false; }

        // Reference fails (secondCollectResult false), buggy succeeds (true)
        // So we assert that secondCollectResult == false (property for reference)
        assertTrue(secondCollectResult == false);
    }
}

