import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 1.5 ether);
        vm.prank(user);
        c.Put{value: 1.5 ether}(block.timestamp);
        vm.prank(user);
        c.Collect(1 ether);
        vm.warp(block.timestamp + 1);
        vm.prank(user);
        bool ok;
        try c.Collect(0.5 ether) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

