pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up caller
        address user = address(0x1234);

        // Fund user and allow sufficient time
        vm.deal(user, 2 ether);
        vm.warp(1000);

        // User puts 1 ether with unlockTime=0, so unlockTime becomes block.timestamp=1000
        vm.prank(user);
        c.Put{value: 1 ether}(0);

        // Warp past unlockTime
        vm.warp(2000);

        // Try Collect(1 ether) — in reference, acc.balance == _am is allowed; in bug, it's not
        bool success;
        vm.prank(user);
        try c.Collect(1 ether) {
            success = true;
        } catch {
            success = false;
        }

        // Reference: success is true, bug: false
        assertTrue(success);
    }
}

