pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Put 1 ether to set balance exactly 1 ether
        vm.deal(address(this), 1 ether);
        c.Put{value: 1 ether}(0);
        // Now Collect(1 ether): reference should succeed, bug reverts
        uint256 lenBefore = c.LogFile().History.length;
        try c.Collect(1 ether) {
            // reference succeeds
        } catch {
            // bug reverts
        }
        uint256 lenAfter = c.LogFile().History.length;
        assertTrue(lenAfter > lenBefore, "Reference adds log entry");
    }
}

