pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 3 ether);
        vm.startPrank(alice);
        // First Put: 2 ether
        c.Put{value: 2 ether}(0);
        // Second Put: 1 ether, total balance = 2 ether
        c.Put{value: 1 ether}(0);
        // Warp to after unlockTime (unlockTime set to block.timestamp after first Put)
        vm.warp(block.timestamp + 1);
        // Now try Collect(2 ether) — exact balance
        bool ok;
        try c.Collect(2 ether) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();
        // Reference: balance >= _am -> ok == true; Bug: balance > _am required -> ok == false
        assertTrue(ok);
    }
}

