pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up: give the test contract (as a fallback recipient) 1 ether via vm.deal
        vm.deal(address(this), 1 ether);
        // Call Put(0) with 1 ether to set balance = 1 ether
        (bool putSuccess, ) = address(c).call{value: 1 ether}(abi.encodeWithSignature("Put(uint256)", 0));
        require(putSuccess, "Put failed");
        // Now attempt Collect(1 ether) — reference succeeds, bug reverts
        bool collectSuccess;
        try c.Collect(1 ether) {
            collectSuccess = true;
        } catch {
            collectSuccess = false;
        }
        // Assert: reference passes (collectSuccess true), bug fails (collectSuccess false)
        assertTrue(collectSuccess, "Collect should succeed in reference");
    }
}
